// The table the OS hands a module at its load (sdk/src/moyos_crt.c).
typedef struct {
    uint32_t version;     // bumped on every append; never on anything else
    uint32_t rows;
    void *fn[];           // row i is the same prototype forever; retired -> a typed stub
} moy_os_table_t;

